2	import path from 'node:path';
3	import { parseArgs } from 'node:util';
4	
5	import { canonicalJson, digestOf } from './canonical.js';
6	import { CachelatticeError, ValidationError } from './errors.js';
7	import { Cachelattice } from './service.js';
8	import { start } from './server.js';
9	
10	const USAGE = `Cachelattice - content-addressed build cache and dependency scheduler.
11	
12	Usage:
13	  node src/cli.js serve [--host H] [--port P] [--data DIR] [--workspace DIR]
14	  node src/cli.js run --graph ID [--data DIR] [--workspace DIR] [--out FILE] [--no-cache]
15	  node src/cli.js stats [--data DIR] [--workspace DIR]
16	  node src/cli.js gc [--data DIR] [--workspace DIR] [--keep KEY]... [--dry-run]
17	
18	The data directory defaults to .cachelattice and the workspace to the current
19	directory. The service prints "Cachelattice listening on http://<host>:<port>"
20	once the port is bound.
21	`;
22	
23	function parse(argv) {
24	  const [command, ...rest] = argv;
25	  const { values } = parseArgs({
26	    args: rest,
27	    options: {
28	      host: { type: 'string', default: '127.0.0.1' },
29	      port: { type: 'string', default: '18091' },
30	      data: { type: 'string', default: '.cachelattice' },
31	      workspace: { type: 'string', default: '.' },
32	      graph: { type: 'string' },
33	      out: { type: 'string' },
34	      cache: { type: 'boolean', default: true },
35	      keep: { type: 'string', multiple: true },
36	      'dry-run': { type: 'boolean', default: false },
37	      help: { type: 'boolean', default: false, short: 'h' },
38	    },
39	    allowPositionals: false,
40	  });
41	  return { command, values };
42	}
43	
44	async function serve(values) {
45	  const port = Number.parseInt(values.port, 10);
46	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
47	    throw new ValidationError('--port must be an integer between 1 and 65535');
48	  }
49	  const { server } = await start({
50	    host: values.host,
51	    port,
52	    dataDirectory: values.data,
53	    workspace: values.workspace,
54	  });
55	  const shutdown = () => {
56	    server.close(() => process.exit(0));
57	  };
58	  process.on('SIGINT', shutdown);
59	  process.on('SIGTERM', shutdown);
60	}
61	
62	async function run(values) {
63	  if (!values.graph) throw new ValidationError('run requires --graph');
64	  const service = new Cachelattice({ dataDirectory: values.data, workspace: values.workspace });
65	  await service.loading;
66	  const result = await service.runGraph(values.graph, { useCache: values.cache });
67	  if (values.out) {
68	    const last = [...result.nodes].sort((left, right) => (left.id < right.id ? -1 : 1)).at(-1);
69	    const { buffer } = await service.cacheGet(last.key);
70	    const target = path.resolve(values.out);
71	    await mkdir(path.dirname(target), { recursive: true });
72	    await writeFile(target, buffer);
73	    process.stdout.write(
74	      `${canonicalJson({ ...result, out: { path: target, digest: digestOf(buffer), size: buffer.length } })}\n`,
75	    );
76	    return;
77	  }
78	  process.stdout.write(`${canonicalJson(result)}\n`);
79	}
80	
81	async function stats(values) {
82	  const service = new Cachelattice({ dataDirectory: values.data, workspace: values.workspace });
83	  await service.loading;
84	  const summary = await service.stats();
85	  const keys = await service.cacheEntries(100000);
86	  process.stdout.write(`${canonicalJson({ ...summary, keys })}\n`);
87	}
88	
89	async function gc(values) {
90	  const service = new Cachelattice({ dataDirectory: values.data, workspace: values.workspace });
