import { mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { Cachelattice } from './src/service.js';

const root = await mkdtemp(path.join(tmpdir(), 'cl-'));
const ws = path.join(root, 'ws');
await mkdir(path.join(ws, 'src'), { recursive: true });
await writeFile(path.join(ws, 'src/app.txt'), 'a\nb\nc\n');
const svc = new Cachelattice({ dataDirectory: path.join(root, 'data'), workspace: ws, ambientEnv: {} });
await svc.loading;

await svc.putAction({ name: 'w1', command: { kind: 'write-file', content: '1' }, inputs: [{ kind: 'file', path: 'src/app.txt' }], env: [] });
await svc.putAction({ name: 'w2', command: { kind: 'write-file', content: '22' }, inputs: [{ kind: 'file', path: 'src/app.txt' }], env: [] });

// limits: cpu=1 slot. Nodes a(needs none, cpu1), b(needs none, cpu0), c(needs none, cpu1)
await svc.putGraph('g', {
  id: 'g', concurrency: 4,
  limits: { cpu: 1, mem: 10 },
  nodes: [
    { id: 'a', action: 'w1', resources: { cpu: 1, mem: 10 } },
    { id: 'b', action: 'w2', resources: { cpu: 0 } },
    { id: 'c', action: 'w1', resources: { cpu: 1 } },
  ],
});

const got = await svc.getGraph('g');
console.log('GRAPH VIEW:', JSON.stringify(got, null, 0).slice(0, 400));

const run = await svc.runGraph('g');
console.log('resource_limits', run.resource_limits);
console.log('peak_resources', run.peak_resources);
console.log('peak_parallel', run.peak_parallel, 'hits/misses', run.cache_hits, run.cache_misses);
console.log('node resources', run.nodes.map(n => [n.id, n.resources]));

// Validation failures
const bad = async (label, body) => {
  try { await svc.putGraph(label, { id: label, ...body }); console.log('NO THROW', label); }
  catch (e) { console.log('400?', e.status, '-', e.message.slice(0, 90)); }
};
await bad('v1', { nodes: [{ id: 'a', action: 'w1' }], limits: [] });
await bad('v2', { nodes: [{ id: 'a', action: 'w1' }], limits: { cpu: 0 } });
await bad('v3', { nodes: [{ id: 'a', action: 'w1' }], limits: { cpu: 1000001 } });
await bad('v4', { nodes: [{ id: 'a', action: 'w1' }], limits: { '1bad': 1 } });
await bad('v5', { nodes: [{ id: 'a', action: 'w1' }], limits: { 'ok.name': 1 } });
await bad('v6', { nodes: [{ id: 'a', action: 'w1', resources: { gpu: 1 } }], limits: { cpu: 1 } });
await bad('v7', { nodes: [{ id: 'a', action: 'w1', resources: { cpu: 2 } }], limits: { cpu: 1 } });
await bad('v8', { nodes: [{ id: 'a', action: 'w1', resources: [] }], limits: { cpu: 1 } });
await bad('v9', { nodes: [{ id: 'a', action: 'w1', resources: { cpu: -1 } }], limits: { cpu: 1 } });
await bad('v10', { nodes: [{ id: 'a', action: 'w1', resources: { 'x'.repeat(33): 1 } }], limits: { ['x'.repeat(33)]: 1 } });

// no-limits graph
await svc.putGraph('plain', { id: 'plain', nodes: [{ id: 'a', action: 'w1' }] });
const r2 = await svc.runGraph('plain');
console.log('plain limits/peak/node:', JSON.stringify(r2.resource_limits), JSON.stringify(r2.peak_resources), JSON.stringify(r2.nodes[0].resources));

await rm(root, { recursive: true, force: true });
